def icon(name):
 return '<svg class="ui-icon" data-icon="'+name+'" viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+ICON_PATHS[name]+'</svg>'
def semantic_icons(markup):
 def convert(m):
  el=m.group(0)
  if not any(c in el for c in ('↗','↓','←','☎','☰','×')): return el
  if 'menu-toggle' in el: name='menu'
  elif 'close-dialog' in el: name='close'
  elif 'data-photo=' in el: name='expand'
  elif 'tel:' in el: name='phone'
  elif 'instagram.com' in el: name='instagram'
  elif 'google.com/maps' in el: name='pin'
  elif 'type="submit"' in el: name='mail'
  elif 'educacao-infantil.html' in el: name='school'
  elif 'ensino-fundamental.html' in el or '#ensino' in el: name='book'
  elif 'Voltar ao início' in el: name='home'
  else: name='calendar'
  return re.sub('[↗↓←☎☰×]',lambda _:icon(name),el)
 markup=re.sub(r'<(?:a|button)\b[^>]*>.*?</(?:a|button)>',convert,markup,flags=re.S)
 return markup.replace('◷',icon('clock'))

